    internal val oui24ToVendorMap: Map<Int, String> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        val map = HashMap<Int, String>(1200)
        for (row in VENDOR_OUI_PACKS) {
            val sep = row.indexOf('|')
            if (sep <= 0) continue
            val vendor = row.substring(0, sep)
            val hex = row.substring(sep + 1)
            var idx = 0
            while (idx + 6 <= hex.length) {
                val key = hex.substring(idx, idx + 6).toInt(16)
                map.putIfAbsent(key, vendor)
                idx += 6
            }
        }
        map
    }

    fun resolve(bssid: String, wpsManufacturer: String? = null): VendorInfo {
        if (MacAddressUtils.isAndroidRedactedMac(bssid)) {
            return VendorInfo(
                ouiPrefix = "02:00:00",
                vendorName = null,
                displayLabel = ANDROID_REDACTED_LABEL,
                isLocallyAdministered = true,
                inferredParentVendor = null,
                isRedactedPlaceholder = true,
            )
        }

        if (!MacAddressUtils.isValidMac(bssid)) {
            return VendorInfo(
                ouiPrefix = null,
                vendorName = null,
                displayLabel = UNKNOWN_VENDOR_LABEL,
                isLocallyAdministered = false,
                inferredParentVendor = null,
                isRedactedPlaceholder = false,
            )
        }

        val oui = MacAddressUtils.extractOuiPrefix(bssid)!!
        val cleanWpsManufacturer = wpsManufacturer?.trim()?.takeIf { it.isNotEmpty() }

        return if (!MacAddressUtils.isLocallyAdministered(bssid)) {
            val key24 = parseOui24(oui)
            val matched = oui24ToVendorMap[key24] ?: cleanWpsManufacturer
            if (matched != null) {
                VendorInfo(
                    ouiPrefix = oui,
                    vendorName = matched,
                    displayLabel = matched,
                    isLocallyAdministered = false,
                    inferredParentVendor = null,
                    isRedactedPlaceholder = false,
                )
            } else {
                VendorInfo(
                    ouiPrefix = oui,
                    vendorName = null,
                    displayLabel = UNKNOWN_VENDOR_LABEL,
                    isLocallyAdministered = false,
                    inferredParentVendor = null,
                    isRedactedPlaceholder = false,
                )
            }
        } else {
            val clearedOui = MacAddressUtils.clearLocallyAdministeredBitOui(bssid)!!
            val parentVendor = oui24ToVendorMap[parseOui24(clearedOui)] ?: cleanWpsManufacturer
            if (parentVendor != null) {
                VendorInfo(
                    ouiPrefix = oui,
                    vendorName = null,
                    displayLabel = "$parentVendor ($RANDOMIZED_VIRTUAL_LABEL)",
                    isLocallyAdministered = true,
                    inferredParentVendor = parentVendor,
                    isRedactedPlaceholder = false,
                )
            } else {
                VendorInfo(
                    ouiPrefix = oui,
                    vendorName = null,
                    displayLabel = RANDOMIZED_VIRTUAL_LABEL,
                    isLocallyAdministered = true,
                    inferredParentVendor = null,
                    isRedactedPlaceholder = false,
                )
            }
        }
    }

    internal fun parseOui24(colonSeparatedOui: String): Int {
        val b0 = colonSeparatedOui.substring(0, 2).toInt(16)
        val b1 = colonSeparatedOui.substring(3, 5).toInt(16)
        val b2 = colonSeparatedOui.substring(6, 8).toInt(16)
        return (b0 shl 16) or (b1 shl 8) or b2
    }
}
